/*
 * Brand Restyle — automated tests (Jasmine)
 * ------------------------------------------------------------------
 * These 10 specs run INSIDE index.html (the Jasmine Spec Runner) and
 * read the CSS RULES you write in main.css. You only edit main.css
 * (and, optionally, one font <link> in the <head>). Leave the page
 * markup and this file exactly as they are.
 *
 * DO NOT EDIT THIS FILE. Make every spec below turn green by giving
 * the page a palette, a web-font stack, and rem-based type.
 * ------------------------------------------------------------------
 */

describe("Brand Restyle — colours, typography & units", function () {

  // ---- helpers --------------------------------------------------

  // Flatten every author style rule into a plain array, skipping
  // Jasmine's own stylesheet and the browser's UA sheets.
  function allRules() {
    var out = [];
    var sheets = document.styleSheets || [];
    for (var i = 0; i < sheets.length; i++) {
      var href = sheets[i].href || "";
      if (/jasmine/i.test(href)) continue;   // ignore Jasmine's CSS
      var rules;
      try { rules = sheets[i].cssRules || sheets[i].rules; }
      catch (e) { continue; }                // cross-origin / unreadable
      if (!rules) continue;
      for (var j = 0; j < rules.length; j++) {
        if (rules[j].selectorText && rules[j].style) out.push(rules[j]);
      }
    }
    return out;
  }

  // First rule whose selector matches (loose contains) a target.
  function ruleFor(selectorPart) {
    var rules = allRules();
    for (var i = 0; i < rules.length; i++) {
      var sel = rules[i].selectorText.toLowerCase();
      if (sel.indexOf(selectorPart) !== -1) return rules[i];
    }
    return null;
  }

  // The :root rule (holds the custom properties), if any.
  function rootRule() { return ruleFor(":root"); }

  // Names of custom properties (--foo) declared on a rule.
  function customPropNames(rule) {
    var names = [];
    if (!rule) return names;
    for (var i = 0; i < rule.style.length; i++) {
      var n = rule.style[i];
      if (n && n.indexOf("--") === 0) names.push(n);
    }
    return names;
  }

  function looksLikeColour(v) {
    if (!v) return false;
    v = v.trim().toLowerCase();
    return /^#([0-9a-f]{3,8})$/.test(v) || /^rgb/.test(v) || /^hsl/.test(v);
  }

  // All declaration values across the author's rules, joined.
  function allDeclText() {
    var rules = allRules(), s = "";
    for (var i = 0; i < rules.length; i++) s += " " + rules[i].cssText;
    return s;
  }

  function countVarUses() {
    var m = allDeclText().match(/var\(\s*--/g);
    return m ? m.length : 0;
  }

  // ---- tests ----------------------------------------------------

  // Test 1
  it("defines a :root rule for the palette", function () {
    expect(rootRule()).not.toBeNull();
  });

  // Test 2
  it("declares at least 3 custom properties on :root", function () {
    expect(customPropNames(rootRule()).length).toBeGreaterThanOrEqual(3);
  });

  // Test 3
  it("at least 3 of those custom properties hold colour values", function () {
    var root = rootRule(), names = customPropNames(root), colours = 0;
    for (var i = 0; i < names.length; i++) {
      if (looksLikeColour(root.style.getPropertyValue(names[i]))) colours++;
    }
    expect(colours).toBeGreaterThanOrEqual(3);
  });

  // Test 4
  it("gives the body a font-family", function () {
    var b = ruleFor("body");
    var ff = b ? b.style.getPropertyValue("font-family") : "";
    expect(ff.trim().length).toBeGreaterThan(0);
  });

  // Test 5
  it("uses a font-family STACK on body (a fallback after a comma)", function () {
    var b = ruleFor("body");
    var ff = b ? b.style.getPropertyValue("font-family") : "";
    expect(ff.indexOf(",")).toBeGreaterThan(0);
  });

  // Test 6
  it("sizes the body font in rem units", function () {
    var b = ruleFor("body");
    var fs = b ? b.style.getPropertyValue("font-size") : "";
    expect(/rem\s*$/.test(fs.trim())).toBe(true);
  });

  // Test 7
  it("sizes the h1 font in rem units", function () {
    var h = ruleFor("h1");
    var fs = h ? h.style.getPropertyValue("font-size") : "";
    expect(/rem\s*$/.test(fs.trim())).toBe(true);
  });

  // Test 8
  it("references the palette with var(--...) at least twice", function () {
    expect(countVarUses()).toBeGreaterThanOrEqual(2);
  });

  // Test 9
  it("applies a palette variable to a text color", function () {
    var rules = allRules(), ok = false;
    for (var i = 0; i < rules.length; i++) {
      var c = rules[i].style.getPropertyValue("color");
      if (c && c.indexOf("var(--") !== -1) { ok = true; break; }
    }
    expect(ok).toBe(true);
  });

  // Test 10
  it("applies a palette variable to a background", function () {
    var rules = allRules(), ok = false;
    for (var i = 0; i < rules.length; i++) {
      var bg = rules[i].style.getPropertyValue("background") ||
               rules[i].style.getPropertyValue("background-color");
      if (bg && bg.indexOf("var(--") !== -1) { ok = true; break; }
    }
    expect(ok).toBe(true);
  });

});
